HttpRequestConfiguration.Body:
{% $string({
  "id": event.id,
  "at": 1,
  "tmax": 500,
  "imp": [
    {
      "id": "1",
      "secure": 1,
      "video": {
        "mimes": ["video/mp4", "video/h264"],
        "minduration": 1,
        "maxduration": $exists(player_params.max_duration) ? $number(player_params.max_duration) : 30,
        "protocols": [1, 2, 3, 4, 5, 6, 7, 8, 11, 12, 13, 14, 15, 16],
        "w": 1920,
        "h": 1080,
        "placement": 1,
        "plcmt": 1,
        "linearity": 1,
        "minbitrate": 2000,
        "maxbitrate": 30000,
        "poddur": $number(session.avail_duration_secs),
        "maxseq": $floor($number(session.avail_duration_secs) / 15),
        "playbackmethod": [1],
        "delivery": [1, 2]
      },
      "bidfloor": $number("YOUR_BIDFLOOR_NUMBER"),
      "ext": {
        "tid": avail.index,
        "tidt": 1,
        "gpid": null,
        "openads": {
          "bidder": {
            "thetradedesk": {
              "publisherId": "YOUR_TTD_PUBLISHER_ID",
              "supplySourceId": "YOUR_SUPPLY_SOURCE_ID"
            }
          }
        }
      }
    }
  ],
  "app": {
    "id": player_params.app_id,
    "name": player_params.app_name,
    "bundle": player_params.app_bundle,
    "domain": player_params.app_domain,
    "publisher": {
      "id": "YOUR_SUPPLY_SOURCE_ID"
    },
    "content": {
      "id": asset.CAID,
      "title": asset.TITLE,
      "series": asset.SERIES,
      "season": asset.SEASON,
      "episode": asset.EPISODE,
      "genre": asset.GENRE,
      "contentrating": asset.CONTENTRATING,
      "language": $exists(asset.LANGUAGE) ? asset.LANGUAGE : "en"
    }
  },
  "device": {
    "ua": session.user_agent,
    "ip": $contains(session.client_ip, ":") ? null : session.client_ip,
    "ipv6": $contains(session.client_ip, ":") ? session.client_ip : null,
    "ifa": player_params.ifa,
    "dnt": $exists(player_params.dnt) ? $number(player_params.dnt) : 0,
    "lmt": $exists(player_params.lmt) ? $number(player_params.lmt) : 0,
    "ext": {
      "ifa_type": player_params.ifa_type
    }
  },
  "user": {
    "eids": player_params.liveRampEnvelope ? [{"source": "liveramp.com", "uids": [{"id": player_params.liveRampEnvelope, "atype": 3}]}] : null,
    "consent": "YOUR_CONSENT_STRING_HERE"
  },
  "ext": {
    "openads": {
      "cache": {
        "collatedvast": {
          "returnbids": false
        }
      }
    },
    "integrationType": "AWSElementalMediaTailor"
  },
  "regs": {
    "coppa": $exists(player_params.coppa) ? $number(player_params.coppa) : 0,
    "gdpr": 1
  }
}) %}
